	'dashboard.tour.step_menu_forever_club_text' => 'Ovdje se otvaraju glavne informacije o FCC-u, objašnjenja sistema i sadržaj koji ti pomaže da razumiješ kako aplikacije, preporuke i alati zajedno doprinose izgradnji Forever poslovanja.',
	'dashboard.tour.step_menu_forever_products_title' => 'Forever proizvodi',
	'dashboard.tour.step_menu_forever_products_text' => 'Ovdje možeš otvoriti sadržaj o proizvodima i članke koje možeš podijeliti uz svoju preporuku. Ovo je važan dio stvaranja interesovanja i usmjeravanja posjetilaca ka Forever internet prodavnici.',
	'dashboard.tour.step_menu_blog_title' => 'Blog',
	'dashboard.tour.step_menu_blog_text' => 'Blog nudi širi obrazovni i poslovni sadržaj koji možeš koristiti u objavama i porukama, kao i za izgradnju povjerenja kroz koristan sadržaj, a ne samo kroz direktnu prodaju.',
	'dashboard.tour.step_menu_contact_title' => 'Kontakt',
	'dashboard.tour.step_menu_contact_text' => 'Ovdje su dostupni kontakt i podrška za dodatna pitanja. Kada ti nešto nije jasno ili ti je potreban pravac, ovo je jedno od mjesta na kojima možeš zatražiti pomoć.',
	'dashboard.tour.step_menu_dashboard_title' => 'Otvori kontrolnu tablu',
	'dashboard.tour.step_menu_dashboard_text' => 'Kontrolna tabla je tvoj komandni centar. Ovdje pratiš svoje signale, učiš kroz vodiče, vidiš šta funkcioniše i odlučuješ koji bi trebalo da bude tvoj sljedeći korak.',
	'dashboard.tour.step_hero_title' => 'Početna stranica tvog rada u FCC-u',
	'dashboard.tour.step_hero_text' => 'Ovaj gornji odjeljak sažima gdje se trenutno nalaziš, na šta se usredsređuješ i koji su ti najbrži načini pristupa aplikacijama, podršci i obrazovnim vodičima.',
	'dashboard.tour.step_growth_title' => 'Signali i otključavanja',
	'dashboard.tour.step_growth_text' => 'Ovdje možeš vidjeti koliko stvarne aktivnosti vodi ka Forever Living internet prodavnici putem tvoje FCC aplikacije, bloga i drugih alata. Taj pokazatelj utiče na tempo podrške vještačke inteligencije i na sljedeće korake koji će ti biti dostupni u planu rasta.',
	'dashboard.tour.step_tutorials_title' => 'Kratki vodiči i edukacija',
	'dashboard.tour.step_tutorials_text' => 'Ovdje otvarate kratka praktična uputstva za konkretne radnje. Tako FCC edukacija izgleda u praksi: ne samo kroz teoriju, već i kroz male korake koje možete odmah primijeniti.',
	'dashboard.tour.step_workbench_title' => 'Radni prostor',
	'dashboard.tour.step_workbench_text' => 'Ovdje odmah vidiš šta funkcioniše, gdje se gubi rezultat i koji djelovi sistema već privlače interesovanje. To ti pomaže da donosiš odluke na osnovu stvarnih signala, a ne nagađanja.',
	'dashboard.tour.step_chart_title' => 'Klikovi koji donose rezultate',
	'dashboard.tour.step_chart_text' => 'Grafikon razdvaja app → Forever, blog → Forever, registracije i kontakte od funnel-a i AI ćaskanja, kako bi jasno vidio/la koji dio sistema stvara stvarni poslovni signal.',
	'dashboard.tour.step_next_action_title' => 'Vaš sljedeći korak',
	'dashboard.tour.step_next_action_text' => 'Ovaj blok ti daje jednu jasnu preporuku šta sada da uradiš. Cilj FCC-a nije da te zatrpa podacima, već da ti pomogne da izabereš najkorisniji sljedeći korak.',
	'dashboard.tour.step_support_title' => 'Podrška i teme vebinara',
	'dashboard.tour.step_support_text' => 'Ovdje možeš da otvoriš podršku, pročitaš odgovore administratora i predložiš teme za vebinare koje želiš da obradimo. To je dio edukacije FCC-a koji pomaže kada zapneš ili želiš bolje razumijevanje.',
